 function intake(){dialog('What Chapter 8 inherits','<p>'+cs().length+' contract boundaries and '+ds().length+' data definitions continue '+esc(project().name)+'.</p>'+badge(realizationHandoffCurrent(project())?'Current Chapter 7 handoff':'Chapter 7 working model · handoff needs review',!realizationHandoffCurrent(project()))+'<p>Existing interface and data object identities are retained. Inherited content remains illustrative until reviewed with the accountable owners.</p><form id="i-intake-form">'+end('Mark inherited inputs reviewed')+'</form>','intake')}
 function pick(id){pause();ghost=null;bridge.state.selected=id;if(contract(project(),id))activeContract=id;if(dataRecord(project(),id)){activeData=id;bridge.state.visible=[...new Set([...bridge.state.visible,'data'])]}if(model().parties.some(p=>p.id===id))activeParty=id;bridge.persist();bridge.render()}
 function setStage(value){stage=value;if(value==='contracts')currentContract()?pick(currentContract().id):bridge.render();else if(value==='data')currentData()?pick(currentData().id):bridge.render();else if(value==='parties')currentParty()?pick(currentParty().id):bridge.render();else bridge.render()}
 // An explicit object link chooses the matching Work surface. Ordinary chapter/tab
 // navigation leaves the architect's manually chosen stage in place.
 function enter(id,{explicit=false}={}){if(!explicit||!id)return;if(dataRecord(project(),id)){stage='data';activeData=id}else if(contract(project(),id)){stage='contracts';activeContract=id}else if(model().parties.some(p=>p.id===id)){stage='parties';activeParty=id}else if(participant(project(),id))stage='contracts';else if(model().lineage.some(l=>l.id===id))stage='lineage'}
 // AIW's proposed contracts (round 12, D-13, DM-17): kept as the person's or dismissed with a reason; a retired contract
