 function proposalReview(){return ghost?'<div class="t-dock-grid"><section><h3>Reviewable change</h3><p>'+esc(ghost.reason)+'</p>'+B('edit-ghost','Review & edit proposal','gold')+'</section><section><h3>Proposed wording</h3><p>'+esc(ghost.record.duplicatePolicy||ghost.record.timeoutPolicy||ghost.record.retentionPolicy)+'</p></section><section><h3>Acceptance</h3><p>Review the edited fields before saving. The proposal does not establish provider agreement or runtime enforcement.</p>'+B('dismiss','Dismiss proposal')+'</section></div>':'';}
