 document.addEventListener('submit',async e=>{if(!e.target.closest('.i-dialog'))return;e.preventDefault();const f=e.target;if(!validateForm(f))return;const raw=formValues(f);if(f.id==='i-editor'||f.id==='i-data-form'){if(context.type==='ghost')await propose(ghost.kind==='contract'?'contract':'data',{...raw,id:ghost.record.id});else if(context.id)await propose(context.type,{...raw,id:context.id});else await send(context.type,raw);}else if(f.id==='i-field-form')await propose('field',{id:context.id,field:{...raw,id:context.fieldId}});else if(f.id==='i-party-form')await send('party',{...raw,id:context.id});else if(f.id==='record-retire-form')await send('record.retire',{ids:context.ids,reason:raw.reason,chapter:8},context.type==='dismiss-seed'?'Dismissed with your reason. AIW will not propose it again.':context.type==='remove-contract'?'Contract removed. It is kept with your reason.':'Retired with your reason. You can restore it.');else if(f.id==='i-lineage-form')await send('lineage',{...raw,id:context.id});else if(f.id==='i-invariant-form'){const fd=new FormData(f);await send('invariant',{...raw,dataIds:fd.getAll('dataIds'),contractIds:fd.getAll('contractIds'),id:context.id});}else if(f.id==='i-remove-field-form')await propose('remove-field',{id:context.id,fieldId:context.fieldId});else if(f.id==='i-remove-lineage-form')await send('remove-lineage',{id:context.id});else if(f.id==='i-intake-form')await send('intake',{},'Inherited boundaries reviewed.');else if(f.id==='i-review-form')await send('record-review',{...raw,id:context.id},'Design review recorded; open findings remain explicit.');else if(f.id==='i-probe-form')applyProbe(raw,context.id);else if(f.id==='i-check-form')await send('check',{...raw,id:lab.id,payload:lab.payload,role:lab.role,scenario:lab.scenario,stamp:lab.stamp,visited:lab.visited},'Design check saved without its synthetic payload.');else if(f.id==='i-handoff-form')await send('handoff',{acknowledge:new FormData(f).has('acknowledge')},'Interfaces and data carried into Security.',chapter9);},{signal});
