 // Field sparks on this studio's editors, and the Co-author panel's way into them (round 2, I2-12).
 sparkStudio({store,signal,dialog:'.i-dialog',recordId:()=>context?.id||null,editors:{'interfaces.contract':id=>editContract(id),'interfaces.data':id=>editData(id),'interfaces.field':id=>{const d=(project().interfaces?.data||[]).find(x=>(x.fields||[]).some(f=>f.id===id));if(d)editField(id,null,d.id);},'interfaces.party':id=>editParty(id),'interfaces.lineage':id=>editLineage(id)}});
