  // An element placed on the canvas: a contract, a data definition or an external participant.
  element(spec){if(spec.type==='data'){editData(null);return;}if(spec.type==='party'){editParty(null);return;}dialog('New interface contract',contractForm({}),'contract',{id:undefined});step(0);},
